for t in [10,15,20,25]:print(t,(ad.obs.pct_counts_mt>t).sum())
print('cells hbb>30', ((ad[:,ad.var_names=='HBB'].X.toarray().ravel()/ad.obs.total_counts*100)>30).sum())

